// Pure Stage13 TOCTOU boundary between consent preview and locked replan.
// Manifest wall-clock timestamps are regenerated by buildManifest(), but
// no user-owned bytes, modes, section ownership or semantic metadata may
// change between the pre-lock proposal and the post-lock reinspection.
import {createHash} from 'node:crypto';

const sha=x=>createHash('sha256').update(x).digest('hex');
function deny(code){const error=new Error(code);error.code=code;throw error;}
function semanticManifest(manifest) {
  if(!manifest||typeof manifest!=='object'||Array.isArray(manifest))
    deny('E_STAGE13_POSTLOCK_MANIFEST_INVALID');
  const {installedAt,updatedAt,...semantic}=manifest;
  return sha(Buffer.from(JSON.stringify(semantic)));
}
export function assertStage13PostLockIdentity(pre,post) {
  if(!pre||!post||!(pre.postimages instanceof Map)||
     !(post.postimages instanceof Map)||
     !(pre.baselines instanceof Map)||!(post.baselines instanceof Map)||
     pre.planFingerprint!==post.planFingerprint||
     pre.actionCount!==post.actionCount||
     pre.postimages.size!==post.postimages.size||
     pre.baselines.size!==post.baselines.size)
    deny('E_STAGE13_POSTLOCK_PLAN_CHANGED');
  for(const [name,item] of pre.postimages) {
    const newer=post.postimages.get(name);
    if(!item||!newer||item.kind!==newer.kind||
       item.priorHash!==newer.priorHash||
       item.postHash!==newer.postHash||
       item.mode!==newer.mode||item.oldMode!==newer.oldMode||
       item.sectionId!==newer.sectionId||
       !pre.baselines.has(name)||!post.baselines.has(name)||
       !Buffer.isBuffer(pre.baselines.get(name))||
       !Buffer.isBuffer(post.baselines.get(name))||
       sha(pre.baselines.get(name))!==sha(post.baselines.get(name)))
      deny('E_STAGE13_PREIMAGE_CHANGED');
  }
  if(semanticManifest(pre.manifest)!==semanticManifest(post.manifest))
    deny('E_STAGE13_POSTLOCK_MANIFEST_CHANGED');
  return Object.freeze({
    classification:'LOCKED_REPLAN_SEMANTICALLY_IDENTICAL',
    writeAuthorized:false,
    actionCount:pre.actionCount,
    timestampDifferenceAllowed:true,
    sourceBytesAndModesMatch:true
  });
}
